 0.8);\n  font-size: 14px;\n  margin: 0;\n}\n.contact-cta-section[_ngcontent-%COMP%]   .contact-cta-note[_ngcontent-%COMP%]   strong[_ngcontent-%COMP%] {\n  color: var(--dark-primary);\n}\n\n\n\n.footer[_ngcontent-%COMP%] {\n  background: var(--bg-dark);\n  color: rgba(255, 255, 255, 0.7);\n  padding: 60px 0 30px;\n  \n\n}\n.footer[_ngcontent-%COMP%]   .footer-grid[_ngcontent-%COMP%] {\n  display: grid;\n  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;\n  gap: 40px;\n  margin-bottom: 40px;\n}\n.footer[_ngcontent-%COMP%]   .footer-column[_ngcontent-%COMP%]   h4[_ngcontent-%COMP%] {\n  color: var(--text-light);\n  font-size: 16px;\n  font-weight: 700;\n  margin-bottom: 20px;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n.footer[_ngcontent-%COMP%]   .footer-column[_ngcontent-%COMP%]   ul[_ngcontent-%COMP%] {\n  list-style: none;\n  padding: 0;\n  margin: 0;\n}\n.footer[_ngcontent-%COMP%]   .footer-column[_ngcontent-%COMP%]   ul[_ngcontent-%COMP%]   li[_ngcontent-%COMP%] {\n  margin-bottom: 12px;\n}\n.footer[_ngcontent-%COMP%]   .footer-column[_ngcontent-%COMP%]   ul[_ngcontent-%COMP%]   li[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  color: rgba(255, 255, 255, 0.7);\n  text-decoration: none;\n  transition: var(--transition-fast);\n  cursor: pointer;\n}\n.footer[_ngcontent-%COMP%]   .footer-column[_ngcontent-%COMP%]   ul[_ngcontent-%COMP%]   li[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n  color: var(--primary-gold);\n  padding-left: 5px;\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  gap: 15px;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  margin-bottom: 20px;\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]:hover {\n  opacity: 0.9;\n  transform: translateX(5px);\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-icon[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 60px; \n\n  height: 60px;\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-icon[_ngcontent-%COMP%]   .logo-image[_ngcontent-%COMP%] {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  border-radius: 10px;\n  \n\n  \n\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-text[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-text[_ngcontent-%COMP%]   .logo-name[_ngcontent-%COMP%] {\n  font-size: 22px;\n  font-weight: 700;\n  letter-spacing: 1px;\n  color: var(--text-light);\n  line-height: 1;\n}\n.footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-text[_ngcontent-%COMP%]   .logo-tagline[_ngcontent-%COMP%] {\n  font-size: 12px;\n  font-weight: 400;\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  color: var(--primary-gold); \n\n  line-height: 1;\n}\n@media (max-width: 768px) {\n  .footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%] {\n    justify-content: center; \n\n    margin-bottom: 30px;\n  }\n  .footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-icon[_ngcontent-%COMP%] {\n    width: 50px;\n    height: 50px;\n  }\n  .footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-text[_ngcontent-%COMP%]   .logo-name[_ngcontent-%COMP%] {\n    font-size: 20px;\n  }\n  .footer[_ngcontent-%COMP%]   .footer-logo[_ngcontent-%COMP%]   .logo-text[_ngcontent-%COMP%]   .logo-tagline[_ngcontent-%COMP%] {\n    font-size: 11px;\n  }\n}\n.footer[_ngcontent-%COMP%]   .footer-emergency[_ngcontent-%COMP%] {\n  padding: 15px;\n  background: rgba(163, 142, 49, 0.1);\n  border: 1px solid rgba(229, 198, 67, 0.3);\n  border-radius: 10px;\n}\n.footer[_ngcontent-%COMP%]   .footer-emergency[_ngcontent-%COMP%]   .emergency-label[_ngcontent-%COMP%] {\n  display: block;\n  font-size: 12px;\n  color: var(--primary-gold);\n  font-weight: 700;\n  margin-bottom: 5px;\n  text-transform: uppercase;\n}\n.footer[_ngcontent-%COMP%]   .footer-emergency[_ngcontent-%COMP%]   .emergency-number[_ngcontent-%COMP%] {\n  display: block;\n  font-size: 20px;\n  font-weight: 800;\n  color: var(--text-light);\n  text-decoration: none;\n}\n.footer[_ngcontent-%COMP%]   .footer-emergency[_ngcontent-%COMP%]   .emergency-number[_ngcontent-%COMP%]:hover {\n  color: var(--primary-gold);\n}\n.footer[_ngcontent-%COMP%]   .footer-badges[_ngcontent-%COMP%] {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.footer[_ngcontent-%COMP%]   .footer-badge[_ngcontent-%COMP%] {\n  padding: 6px 12px;\n  background: rgba(163, 142, 49, 0.1);\n  border: 1px solid rgba(229, 198, 67, 0.3);\n  border-radius: 15px;\n  font-size: 11px;\n  color: var(--primary-gold);\n  font-weight: 600;\n}\n.footer[_ngcontent-%COMP%]   .footer-location[_ngcontent-%COMP%] {\n  line-height: 2;\n  font-size: 14px;\n}\n.footer[_ngcontent-%COMP%]   .footer-bottom[_ngcontent-%COMP%] {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding-top: 30px;\n  border-top: 1px solid rgba(255, 255, 255, 0.1);\n  flex-wrap: wrap;\n  gap: 20px;\n}\n.footer[_ngcontent-%COMP%]   .footer-copyright[_ngcontent-%COMP%] {\n  font-size: 14px;\n}\n.footer[_ngcontent-%COMP%]   .footer-legal[_ngcontent-%COMP%] {\n  display: flex;\n  gap: 15px;\n  align-items: center;\n  font-size: 14px;\n}\n.footer[_ngcontent-%COMP%]   .footer-legal[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  color: rgba(255, 255, 255, 0.7);\n  text-decoration: none;\n  transition: var(--transition-fast);\n}\n.footer[_ngcontent-%COMP%]   .footer-legal[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n  color: var(--primary-gold);\n}\n.footer[_ngcontent-%COMP%]   .footer-legal[_ngcontent-%COMP%]   span[_ngcontent-%COMP%] {\n  color: rgba(255, 255, 255, 0.3);\n}\n.footer[_ngcontent-%COMP%]   .footer-disclaimer[_ngcontent-%COMP%] {\n  margin-top: 30px;\n  padding: 20px;\n  background: rgba(255, 255, 255, 0.03);\n  border-radius: 10px;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n}\n.footer[_ngcontent-%COMP%]   .footer-disclaimer[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.8;\n  color: rgba(255, 255, 255, 0.6);\n}\n.footer[_ngcontent-%COMP%]   .footer-disclaimer[_ngcontent-%COMP%]   strong[_ngcontent-%COMP%] {\n  color: var(--primary-gold);\n}\n\n\n\n\n\n@media (max-width: 1024px) {\n  .operation-grid[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n    gap: 40px;\n  }\n  .process-timeline[_ngcontent-%COMP%]::before {\n    display: none;\n  }\n  .process-step[_ngcontent-%COMP%] {\n    flex-direction: column;\n    align-items: center;\n    text-align: center;\n  }\n}\n@media (max-width: 768px) {\n  .page-hero[_ngcontent-%COMP%] {\n    padding: 120px 0 60px;\n  }\n  .section[_ngcontent-%COMP%] {\n    padding: 60px 0;\n  }\n  .section-header[_ngcontent-%COMP%] {\n    margin-bottom: 40px;\n  }\n  .hero-stats[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n    gap: 20px;\n  }\n  .features-grid[_ngcontent-%COMP%], .equipment-grid[_ngcontent-%COMP%], .zones-grid[_ngcontent-%COMP%], .testimonials-grid[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n  }\n  .operation-content[_ngcontent-%COMP%] {\n    padding: 30px;\n  }\n  .operations-tabs[_ngcontent-%COMP%] {\n    flex-direction: column;\n    align-items: stretch;\n  }\n  .operations-tabs[_ngcontent-%COMP%]   .tab-btn[_ngcontent-%COMP%] {\n    width: 100%;\n  }\n  .cta-buttons[_ngcontent-%COMP%] {\n    flex-direction: column;\n    align-items: stretch;\n  }\n  .cta-buttons[_ngcontent-%COMP%]   .btn[_ngcontent-%COMP%] {\n    width: 100%;\n  }\n}\n@media (max-width: 480px) {\n  .page-hero[_ngcontent-%COMP%] {\n    padding: 100px 0 50px;\n  }\n  .feature-card[_ngcontent-%COMP%] {\n    height: 350px;\n  }\n  .operation-content[_ngcontent-%COMP%] {\n    padding: 20px;\n  }\n  .equipment-card[_ngcontent-%COMP%], .zone-card[_ngcontent-%COMP%], .testimonial-card[_ngcontent-%COMP%] {\n    padding: 25px;\n  }\n}\n/